function securityScanner(code) {
  const issues = [];
  // فحص الثغرات الشائعة
  if (code.includes('process.env') && !code.includes('require')) {
    issues.push('Potential hardcoded secret or insecure environment access.');
  }
  if (code.includes('eval(')) {
    issues.push('Security Risk: Use of eval() detected.');
  }
  if (code.includes('SELECT * FROM')) {
    issues.push('Potential SQL Injection vulnerability.');
  }

  return {
    isSafe: issues.length === 0,
    issues: issues
  };
}
